import React, { useState, useEffect } from 'react';
import { allCountries, getCountryLabel } from './countryMapping';
import { getPublisherLabel } from './publisherMapping';
import './App.css';

function CountryOntologyPage() {
  const [selectedCountry, setSelectedCountry] = useState('');
  const [ontologies, setOntologies] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetch('http://localhost:4000/api/all')
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch ontologies');
        return res.json();
      })
      .then(data => {
        setOntologies(data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  // Helper: Find ontologies published by the selected country
  function getPublishedByCountry(ontologies, countryIri) {
    return ontologies.filter(onto => {
      if (!onto.publishers || !onto.publisherCountries) return false;
      return onto.publisherCountries.some(
        c => c === countryIri
      );
    });
  }

  // Helper: Find ontologies reused by the selected country
  function getReusedByCountry(ontologies, countryIri) {
    // Assume each ontology has a 'reusingCountries' array (like requiringLocations)
    return ontologies.filter(onto => {
      if (!onto.reusingCountries) return false;
      return onto.reusingCountries.includes(countryIri);
    });
  }

  const publishedOntologies = selectedCountry ? getPublishedByCountry(ontologies, selectedCountry) : [];
  const reusedOntologies = selectedCountry ? getReusedByCountry(ontologies, selectedCountry) : [];

  return (
    <div className="country-ontology-layout">
      <div className="country-ontology-header">
        <h2>Ontologies by Country</h2>
        <select
          value={selectedCountry}
          onChange={e => setSelectedCountry(e.target.value)}
        >
          <option value="">Select a country...</option>
          {allCountries.map(c => (
            <option key={c.iri} value={c.iri}>{c.label}</option>
          ))}
        </select>
      </div>
      {loading && <div>Loading...</div>}
      {error && <div style={{ color: 'red' }}>{error}</div>}
      {!loading && !error && selectedCountry && (
        <div className="country-ontology-panels">
          <div className="country-ontology-panel">
            <h3>Ontologies Reused by {getCountryLabel(selectedCountry)}</h3>
            {reusedOntologies.length === 0 ? (
              <div>No ontologies found.</div>
            ) : (
              <ul>
                {reusedOntologies.map((onto, idx) => (
                  <li key={idx}>
                    <b>{onto.title}</b> {onto.publishers && onto.publishers.length > 0 && (
                      <span>by {onto.publishers.map(getPublisherLabel).join(', ')}</span>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
          <div className="country-ontology-panel">
            <h3>Ontologies Published by {getCountryLabel(selectedCountry)}</h3>
            {publishedOntologies.length === 0 ? (
              <div>No ontologies found.</div>
            ) : (
              <ul>
                {publishedOntologies.map((onto, idx) => (
                  <li key={idx}>
                    <b>{onto.title}</b> {onto.publishers && onto.publishers.length > 0 && (
                      <span>by {onto.publishers.map(getPublisherLabel).join(', ')}</span>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default CountryOntologyPage;
